// План specs/invoices.md 4.1 / 4.2 (#70ca62, связан #dce958). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Ничего не сохраняет (@prod-safe):
// имя счёта правится локально на форме New Invoice, кнопка Create Invoice не нажимается.
// Источник: тикет — Escape при повторном редактировании Invoice name возвращает прежнее значение, а не очищает.
// Комментарий программиста: New Invoice → Invoice name → ввод → Enter → карандаш → Escape → имя осталось. Факты 17.11: Escape возвращает прежнее имя.
// Не сверено с сайтом при записи: разметка строки «Invoice name:» — как в invoice-helpers (кнопка с именем/«Add name» + карандаш).
import { test, expect } from '../../fixtures';
import { ROLE, invoiceNameRow, openNewInvoiceForm } from './invoice-helpers';

test.describe('Invoice name — Escape (#70ca62)', () => {
  test('Name entered with Enter → pencil → type something else → Escape returns the previous name #70ca62 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openNewInvoiceForm(page);
    const row = invoiceNameRow(page);
    const first = 'QA-AUTO 70ca62 first';

    await row.getByRole('button', { name: 'Add name', exact: true }).click();
    await row.getByRole('textbox').fill(first);
    await row.getByRole('textbox').press('Enter');
    await expect(row.getByRole('button', { name: first, exact: true })).toBeVisible();

    // Карандаш → другой текст → Escape: прежнее имя (не новое и не пустое)
    await row.getByRole('button').filter({ has: page.locator('svg') }).last().click();
    const input = row.getByRole('textbox');
    await expect(input).toHaveValue(first);
    await input.fill('QA-AUTO 70ca62 changed');
    await input.press('Escape');
    await expect(row.getByRole('button', { name: first, exact: true })).toBeVisible();
    await expect(row.getByRole('textbox')).toHaveCount(0);

    // Карандаш → очистить поле → Escape: имя на месте
    await row.getByRole('button').filter({ has: page.locator('svg') }).last().click();
    await row.getByRole('textbox').fill('');
    await row.getByRole('textbox').press('Escape');
    await expect(row.getByRole('button', { name: first, exact: true })).toBeVisible();

    // Карандаш → новое имя → Enter: сохраняется новое
    await row.getByRole('button').filter({ has: page.locator('svg') }).last().click();
    await row.getByRole('textbox').fill('QA-AUTO 70ca62 second');
    await row.getByRole('textbox').press('Enter');
    await expect(row.getByRole('button', { name: 'QA-AUTO 70ca62 second', exact: true })).toBeVisible();
  });

  test('Empty name + Escape stays "Add name" #70ca62 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(ROLE);
    await openNewInvoiceForm(page);
    const row = invoiceNameRow(page);
    await row.getByRole('button', { name: 'Add name', exact: true }).click();
    await row.getByRole('textbox').fill('QA-AUTO 70ca62 typed');
    await row.getByRole('textbox').press('Escape');
    await expect(row.getByRole('button', { name: 'Add name', exact: true })).toBeVisible();
  });
});
